import java.util.Arrays;
class BookingReceipt {private final String bookingId;private final String[] seatNumbers;public BookingReceipt(String id,String[] seats){bookingId=id;seatNumbers=Arrays.copyOf(seats,seats.length);}public String getBookingId(){return bookingId;}public String[] getSeatNumbers(){return Arrays.copyOf(seatNumbers,seatNumbers.length);}public BookingReceipt withUpdatedSeat(int i,String s){if(i<0||i>=seatNumbers.length)throw new IndexOutOfBoundsException("Invalid seat index");String[] a=getSeatNumbers();a[i]=s;return new BookingReceipt(bookingId,a);}}
class GroupBookingReceipt extends BookingReceipt {private final int groupSize;public GroupBookingReceipt(String id,String[] seats,int n){super(id,seats);groupSize=n;}public int getGroupSize(){return groupSize;}}
public class BookingSettlement {static String processNightlySettlement(BookingReceipt[] a){int p=0,n=0,g=0,i=0;for(BookingReceipt x:a){if(x==null){n++;continue;}p++;if(x instanceof GroupBookingReceipt)g++;else i++;}return p+" processed | "+n+" null skipped | "+g+" group | "+i+" individual";}
public static void main(String[] args){BookingReceipt b=new BookingReceipt("CH-1001",new String[]{"A1","A2"});String[] s=b.getSeatNumbers();s[0]="X";System.out.println(b.getSeatNumbers()[0]);BookingReceipt u=b.withUpdatedSeat(1,"A3");System.out.println(Arrays.toString(b.getSeatNumbers()));System.out.println(Arrays.toString(u.getSeatNumbers()));BookingReceipt[] a={new GroupBookingReceipt("CH-2002",new String[]{"B1","B2"},2),null,new BookingReceipt("CH-3003",new String[]{"C1"})};System.out.println(processNightlySettlement(a));}}
